INSERT INTO saham_phal (saham_key,language,signifies,phal_anukul,phal_pratikul) VALUES
('punya','hi','वर्ष का समग्र पुण्य-सौभाग्य','वर्ष का समग्र पुण्य-सौभाग्य — सहमेश बली, शुभ-स्थित व अ-अस्त होने पर वर्ष शुभ-फलदायी; फल सहमेश की मुद्दा-दशा या गणित-दिवस पर।','सहमेश निर्बल, अस्त या पाप-पीड़ित होने पर वर्ष में सौभाग्य-कमी; उपाय रखें।'),
('guru','hi','गुरुजन व बड़ों का आशीर्वाद','गुरुजन व बड़ों का आशीर्वाद — सहमेश बली, शुभ-स्थित व अ-अस्त होने पर गुरु-कृपा और मार्गदर्शन; फल सहमेश की मुद्दा-दशा या गणित-दिवस पर।','सहमेश निर्बल, अस्त या पाप-पीड़ित होने पर गुरुजनों से दूरी; उपाय रखें।'),
('gyan','hi','विद्या-ज्ञान','विद्या-ज्ञान — सहमेश बली, शुभ-स्थित व अ-अस्त होने पर अध्ययन में सफलता; फल सहमेश की मुद्दा-दशा या गणित-दिवस पर।','सहमेश निर्बल, अस्त या पाप-पीड़ित होने पर विद्या में व्यवधान; उपाय रखें।'),
('yash','hi','कीर्ति-यश','कीर्ति-यश — सहमेश बली, शुभ-स्थित व अ-अस्त होने पर मान-प्रतिष्ठा की वृद्धि; फल सहमेश की मुद्दा-दशा या गणित-दिवस पर।','सहमेश निर्बल, अस्त या पाप-पीड़ित होने पर अपयश का भय; उपाय रखें।'),
('mitra','hi','मित्र-सहयोग','मित्र-सहयोग — सहमेश बली, शुभ-स्थित व अ-अस्त होने पर मित्रों से लाभ; फल सहमेश की मुद्दा-दशा या गणित-दिवस पर।','सहमेश निर्बल, अस्त या पाप-पीड़ित होने पर मित्र-वियोग/धोखा; उपाय रखें।'),
('mahatmya','hi','महत्ता-प्रभाव','महत्ता-प्रभाव — सहमेश बली, शुभ-स्थित व अ-अस्त होने पर समाज में प्रभाव बढ़ेगा; फल सहमेश की मुद्दा-दशा या गणित-दिवस पर।','सहमेश निर्बल, अस्त या पाप-पीड़ित होने पर प्रभाव-क्षय; उपाय रखें।'),
('asha','hi','मनोकामना','मनोकामना — सहमेश बली, शुभ-स्थित व अ-अस्त होने पर आशाएँ फलेंगी; फल सहमेश की मुद्दा-दशा या गणित-दिवस पर।','सहमेश निर्बल, अस्त या पाप-पीड़ित होने पर मनोरथ में विलंब; उपाय रखें।'),
('samarthya','hi','कार्य-शक्ति','कार्य-शक्ति — सहमेश बली, शुभ-स्थित व अ-अस्त होने पर कार्यक्षमता प्रबल; फल सहमेश की मुद्दा-दशा या गणित-दिवस पर।','सहमेश निर्बल, अस्त या पाप-पीड़ित होने पर शक्ति-संकोच; उपाय रखें।'),
('bhratru','hi','भाई-बहन','भाई-बहन — सहमेश बली, शुभ-स्थित व अ-अस्त होने पर भाई-पक्ष से सुख; फल सहमेश की मुद्दा-दशा या गणित-दिवस पर।','सहमेश निर्बल, अस्त या पाप-पीड़ित होने पर भाई-पक्ष की चिंता; उपाय रखें।'),
('gaurav','hi','सम्मान','सम्मान — सहमेश बली, शुभ-स्थित व अ-अस्त होने पर सम्मान-प्राप्ति; फल सहमेश की मुद्दा-दशा या गणित-दिवस पर।','सहमेश निर्बल, अस्त या पाप-पीड़ित होने पर मान-हानि का भय; उपाय रखें।'),
('rajya','hi','राज्य/सरकार-पक्ष, पद','राज्य/सरकार-पक्ष, पद — सहमेश बली, शुभ-स्थित व अ-अस्त होने पर राज्य-पक्ष से लाभ/पद; फल सहमेश की मुद्दा-दशा या गणित-दिवस पर।','सहमेश निर्बल, अस्त या पाप-पीड़ित होने पर सरकारी बाधा; उपाय रखें।'),
('tata','hi','पिता','पिता — सहमेश बली, शुभ-स्थित व अ-अस्त होने पर पिता का सुख-सहयोग; फल सहमेश की मुद्दा-दशा या गणित-दिवस पर।','सहमेश निर्बल, अस्त या पाप-पीड़ित होने पर पिता के स्वास्थ्य/संबंध की चिंता; उपाय रखें।'),
('matru','hi','माता','माता — सहमेश बली, शुभ-स्थित व अ-अस्त होने पर माता का सुख; फल सहमेश की मुद्दा-दशा या गणित-दिवस पर।','सहमेश निर्बल, अस्त या पाप-पीड़ित होने पर माता-पक्ष की चिंता; उपाय रखें।'),
('suta','hi','संतान','संतान — सहमेश बली, शुभ-स्थित व अ-अस्त होने पर संतान-सुख/शुभ समाचार; फल सहमेश की मुद्दा-दशा या गणित-दिवस पर।','सहमेश निर्बल, अस्त या पाप-पीड़ित होने पर संतान-विषय की चिंता; उपाय रखें।'),
('jeevit','hi','जीवनी-शक्ति/आयु','जीवनी-शक्ति/आयु — सहमेश बली, शुभ-स्थित व अ-अस्त होने पर आरोग्य-आयुबल; फल सहमेश की मुद्दा-दशा या गणित-दिवस पर।','सहमेश निर्बल, अस्त या पाप-पीड़ित होने पर जीवनी-शक्ति में कमी; उपाय रखें।'),
('ambu','hi','जल-संबंधी लाभ-भय','जल-संबंधी लाभ-भय — सहमेश बली, शुभ-स्थित व अ-अस्त होने पर जल/तरल क्षेत्र से लाभ; फल सहमेश की मुद्दा-दशा या गणित-दिवस पर।','सहमेश निर्बल, अस्त या पाप-पीड़ित होने पर जल से भय-हानि; उपाय रखें।'),
('karma','hi','कार्य-व्यवसाय','कार्य-व्यवसाय — सहमेश बली, शुभ-स्थित व अ-अस्त होने पर कार्यक्षेत्र में प्रगति; फल सहमेश की मुद्दा-दशा या गणित-दिवस पर।','सहमेश निर्बल, अस्त या पाप-पीड़ित होने पर कार्य में रुकावट; उपाय रखें।'),
('roga','hi','रोग','रोग — सहम पाप-प्रभाव/बली होने पर रोग-भय सक्रिय — स्वास्थ्य-अनुशासन रखें।','सहम शुभ-दृष्ट/नियंत्रित होने पर रोग से राहत/नियंत्रण।'),
('manmatha','hi','काम/प्रेम-आकर्षण','काम/प्रेम-आकर्षण — सहमेश बली, शुभ-स्थित व अ-अस्त होने पर प्रेम-संबंध अनुकूल; फल सहमेश की मुद्दा-दशा या गणित-दिवस पर।','सहमेश निर्बल, अस्त या पाप-पीड़ित होने पर आकर्षण से भटकाव; उपाय रखें।'),
('kali','hi','कलह','कलह — सहम पाप-प्रभाव/बली होने पर कलह-विवाद का भय — वाणी-संयम।','सहम शुभ-दृष्ट/नियंत्रित होने पर विवादों से राहत।'),
('kshama','hi','सहनशीलता','सहनशीलता — सहमेश बली, शुभ-स्थित व अ-अस्त होने पर धैर्य-क्षमा का बल; फल सहमेश की मुद्दा-दशा या गणित-दिवस पर।','सहमेश निर्बल, अस्त या पाप-पीड़ित होने पर सहनशीलता की परीक्षा; उपाय रखें।'),
('shastra','hi','शास्त्र-अध्ययन','शास्त्र-अध्ययन — सहमेश बली, शुभ-स्थित व अ-अस्त होने पर गूढ़/शास्त्र-अध्ययन में सफलता; फल सहमेश की मुद्दा-दशा या गणित-दिवस पर।','सहमेश निर्बल, अस्त या पाप-पीड़ित होने पर अध्ययन में विघ्न; उपाय रखें।'),
('bandhu','hi','बन्धु-वर्ग','बन्धु-वर्ग — सहमेश बली, शुभ-स्थित व अ-अस्त होने पर बन्धुओं से सहयोग; फल सहमेश की मुद्दा-दशा या गणित-दिवस पर।','सहमेश निर्बल, अस्त या पाप-पीड़ित होने पर बन्धु-विरोध; उपाय रखें।'),
('bandaka','hi','अवरोध/बंधक','अवरोध/बंधक — सहम पाप-प्रभाव/बली होने पर रुकावट-गिरवी का योग — लेन-देन सावधानी।','सहम शुभ-दृष्ट/नियंत्रित होने पर अवरोध हटेंगे।'),
('mrityu','hi','मृत्यु-तुल्य संकट','मृत्यु-तुल्य संकट — सहम पाप-प्रभाव/बली होने पर संकट-भय सक्रिय — जोखिम टालें।','सहम शुभ-दृष्ट/नियंत्रित होने पर संकट से रक्षा।'),
('pardesh','hi','विदेश/दूर-यात्रा','विदेश/दूर-यात्रा — सहमेश बली, शुभ-स्थित व अ-अस्त होने पर यात्रा-प्रवास से लाभ; फल सहमेश की मुद्दा-दशा या गणित-दिवस पर।','सहमेश निर्बल, अस्त या पाप-पीड़ित होने पर यात्रा में कष्ट; उपाय रखें।'),
('dhana','hi','धन-लाभ','धन-लाभ — सहमेश बली, शुभ-स्थित व अ-अस्त होने पर धन-आगम अनुकूल; फल सहमेश की मुद्दा-दशा या गणित-दिवस पर।','सहमेश निर्बल, अस्त या पाप-पीड़ित होने पर धन-संकोच; उपाय रखें।'),
('anyadara','hi','अनुचित आकर्षण','अनुचित आकर्षण — सहम पाप-प्रभाव/बली होने पर मर्यादा-भंग का भय — संयम रखें।','सहम शुभ-दृष्ट/नियंत्रित होने पर संयम बना रहेगा।'),
('anyakarma','hi','गौण/अतिरिक्त कार्य','गौण/अतिरिक्त कार्य — सहमेश बली, शुभ-स्थित व अ-अस्त होने पर दूसरे कार्यों से लाभ; फल सहमेश की मुद्दा-दशा या गणित-दिवस पर।','सहमेश निर्बल, अस्त या पाप-पीड़ित होने पर कार्य-बिखराव; उपाय रखें।'),
('vanik','hi','वाणिज्य','वाणिज्य — सहमेश बली, शुभ-स्थित व अ-अस्त होने पर व्यापार-लाभ; फल सहमेश की मुद्दा-दशा या गणित-दिवस पर।','सहमेश निर्बल, अस्त या पाप-पीड़ित होने पर व्यापार में मंदी; उपाय रखें।'),
('karyasiddhi','hi','कार्य-सफलता','कार्य-सफलता — सहमेश बली, शुभ-स्थित व अ-अस्त होने पर रुके कार्य सिद्ध होंगे; फल सहमेश की मुद्दा-दशा या गणित-दिवस पर।','सहमेश निर्बल, अस्त या पाप-पीड़ित होने पर कार्यसिद्धि में विलंब; उपाय रखें।'),
('vivaha','hi','विवाह','विवाह — सहमेश बली, शुभ-स्थित व अ-अस्त होने पर विवाह/संबंध-योग; फल सहमेश की मुद्दा-दशा या गणित-दिवस पर।','सहमेश निर्बल, अस्त या पाप-पीड़ित होने पर विवाह में विलंब; उपाय रखें।'),
('suti','hi','संतान-जन्म','संतान-जन्म — सहमेश बली, शुभ-स्थित व अ-अस्त होने पर संतान-जन्म/शुभ वृद्धि; फल सहमेश की मुद्दा-दशा या गणित-दिवस पर।','सहमेश निर्बल, अस्त या पाप-पीड़ित होने पर प्रसव-विषय में सावधानी; उपाय रखें।'),
('santapa','hi','मानसिक क्लेश','मानसिक क्लेश — सहम पाप-प्रभाव/बली होने पर क्लेश-चिंता सक्रिय — मन का ध्यान रखें।','सहम शुभ-दृष्ट/नियंत्रित होने पर मानसिक शांति।'),
('shraddha','hi','श्रद्धा-भक्ति','श्रद्धा-भक्ति — सहमेश बली, शुभ-स्थित व अ-अस्त होने पर धर्म-कार्य में मन; फल सहमेश की मुद्दा-दशा या गणित-दिवस पर।','सहमेश निर्बल, अस्त या पाप-पीड़ित होने पर श्रद्धा में कमी; उपाय रखें।'),
('preeti','hi','प्रेम-सौहार्द','प्रेम-सौहार्द — सहमेश बली, शुभ-स्थित व अ-अस्त होने पर संबंधों में मिठास; फल सहमेश की मुद्दा-दशा या गणित-दिवस पर।','सहमेश निर्बल, अस्त या पाप-पीड़ित होने पर प्रीति-भंग का भय; उपाय रखें।'),
('bala','hi','शारीरिक बल','शारीरिक बल — सहमेश बली, शुभ-स्थित व अ-अस्त होने पर बल-ऊर्जा अनुकूल; फल सहमेश की मुद्दा-दशा या गणित-दिवस पर।','सहमेश निर्बल, अस्त या पाप-पीड़ित होने पर बल-क्षय; उपाय रखें।'),
('tanu','hi','देह-स्वास्थ्य','देह-स्वास्थ्य — सहमेश बली, शुभ-स्थित व अ-अस्त होने पर स्वास्थ्य अनुकूल; फल सहमेश की मुद्दा-दशा या गणित-दिवस पर।','सहमेश निर्बल, अस्त या पाप-पीड़ित होने पर देह-कष्ट; उपाय रखें।'),
('jadya','hi','जड़ता-आलस्य','जड़ता-आलस्य — सहम पाप-प्रभाव/बली होने पर जड़ता-भ्रम का योग — निर्णय टालें नहीं।','सहम शुभ-दृष्ट/नियंत्रित होने पर सक्रियता लौटेगी।'),
('vyapara','hi','व्यवसाय-लेनदेन','व्यवसाय-लेनदेन — सहमेश बली, शुभ-स्थित व अ-अस्त होने पर सौदों में लाभ; फल सहमेश की मुद्दा-दशा या गणित-दिवस पर।','सहमेश निर्बल, अस्त या पाप-पीड़ित होने पर लेनदेन में हानि; उपाय रखें।'),
('paniyapatana','hi','जल-दुर्घटना भय','जल-दुर्घटना भय — सहम पाप-प्रभाव/बली होने पर जल-यात्रा/जल से जोखिम — सावधानी।','सहम शुभ-दृष्ट/नियंत्रित होने पर जल-भय से रक्षा।'),
('ripu','hi','शत्रु','शत्रु — सहम पाप-प्रभाव/बली होने पर शत्रु-पक्ष सक्रिय — सतर्क रहें।','सहम शुभ-दृष्ट/नियंत्रित होने पर शत्रुओं पर नियंत्रण।'),
('shaurya','hi','वीरता-साहस','वीरता-साहस — सहमेश बली, शुभ-स्थित व अ-अस्त होने पर साहसिक सफलता; फल सहमेश की मुद्दा-दशा या गणित-दिवस पर।','सहमेश निर्बल, अस्त या पाप-पीड़ित होने पर साहस की परीक्षा; उपाय रखें।'),
('upaya','hi','उपाय-युक्ति','उपाय-युक्ति — सहमेश बली, शुभ-स्थित व अ-अस्त होने पर युक्ति से समाधान; फल सहमेश की मुद्दा-दशा या गणित-दिवस पर।','सहमेश निर्बल, अस्त या पाप-पीड़ित होने पर उपाय देर से फलेंगे; उपाय रखें।'),
('daridra','hi','अभाव-दरिद्रता','अभाव-दरिद्रता — सहम पाप-प्रभाव/बली होने पर अभाव का भय — व्यय-नियंत्रण।','सहम शुभ-दृष्ट/नियंत्रित होने पर अभाव से मुक्ति।'),
('guruta','hi','बड़प्पन-गौरव','बड़प्पन-गौरव — सहमेश बली, शुभ-स्थित व अ-अस्त होने पर गुरुता-पद की प्राप्ति; फल सहमेश की मुद्दा-दशा या गणित-दिवस पर।','सहमेश निर्बल, अस्त या पाप-पीड़ित होने पर गौरव में कमी; उपाय रखें।'),
('jalapatha','hi','समुद्र/जल-यात्रा','समुद्र/जल-यात्रा — सहमेश बली, शुभ-स्थित व अ-अस्त होने पर जल-मार्ग से लाभ; फल सहमेश की मुद्दा-दशा या गणित-दिवस पर।','सहमेश निर्बल, अस्त या पाप-पीड़ित होने पर जल-यात्रा में विघ्न; उपाय रखें।'),
('bandhana','hi','बंधन-अवरोध','बंधन-अवरोध — सहम पाप-प्रभाव/बली होने पर बंधन-भय — विधिक/नियम सावधानी।','सहम शुभ-दृष्ट/नियंत्रित होने पर बंधनों से मुक्ति।'),
('duhita','hi','कन्या-संतान','कन्या-संतान — सहमेश बली, शुभ-स्थित व अ-अस्त होने पर कन्या-संतान/कन्या-पक्ष शुभ; फल सहमेश की मुद्दा-दशा या गणित-दिवस पर।','सहमेश निर्बल, अस्त या पाप-पीड़ित होने पर कन्या-पक्ष की चिंता; उपाय रखें।'),
('ashva','hi','वाहन','वाहन — सहमेश बली, शुभ-स्थित व अ-अस्त होने पर वाहन-सुख/नया वाहन; फल सहमेश की मुद्दा-दशा या गणित-दिवस पर।','सहमेश निर्बल, अस्त या पाप-पीड़ित होने पर वाहन से सावधानी; उपाय रखें।')
