-- =============================================================================
-- Auto Business — 50 Sahams (Tajik Neelkanthi) — migration 015
-- Formula table (data-driven), phal sentences, config. Uses existing
-- Varshaphal engine (varsha lagna, planets, houses) + shared Dignity/
-- Combustion/Shadbala services. Renumbered from the uploaded 013 to 015.
-- =============================================================================
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS saham_definitions (
    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    saham_key VARCHAR(20) NOT NULL, seq TINYINT NOT NULL, name_hi VARCHAR(48) NOT NULL,
    a_day VARCHAR(20) NOT NULL, b_day VARCHAR(20) NOT NULL, c_day VARCHAR(20) NOT NULL,
    a_night VARCHAR(20) NOT NULL, b_night VARCHAR(20) NOT NULL, c_night VARCHAR(20) NOT NULL,
    sekata TINYINT NOT NULL DEFAULT 1, nature VARCHAR(8) NOT NULL DEFAULT 'shubh',
    special VARCHAR(160) NULL,
    updated_by_staff_id BIGINT UNSIGNED NULL,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id), UNIQUE KEY uq_sd (saham_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- Tokens: SUN MOON MARS MERCURY JUPITER VENUS SATURN LAGNA LAGNA_LORD PUNYA
-- GURU_SAHAM VIDYA_SAHAM H2 H6 H8 H9 H11 H2_LORD H9_LORD SUN_SIGN_LORD
-- MOON_SIGN_LORD SUN_EXALT(=10.0) MOON_EXALT(=33.0) KARKARDHA(=105.0)

ON DUPLICATE KEY UPDATE a_day=VALUES(a_day),b_day=VALUES(b_day),c_day=VALUES(c_day),
a_night=VALUES(a_night),b_night=VALUES(b_night),c_night=VALUES(c_night),sekata=VALUES(sekata),
nature=VALUES(nature),special=VALUES(special),name_hi=VALUES(name_hi),seq=VALUES(seq);

CREATE TABLE IF NOT EXISTS saham_phal (
    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    saham_key VARCHAR(20) NOT NULL, language VARCHAR(8) NOT NULL DEFAULT 'hi',
    signifies VARCHAR(96) NULL, phal_anukul TEXT NULL, phal_pratikul TEXT NULL,
    updated_by_staff_id BIGINT UNSIGNED NULL,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id), UNIQUE KEY uq_sp (saham_key, language)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ON DUPLICATE KEY UPDATE signifies=VALUES(signifies),phal_anukul=VALUES(phal_anukul),phal_pratikul=VALUES(phal_pratikul);

ON DUPLICATE KEY UPDATE cfg_value=cfg_value;
-- End of migration 015.